// Confirms the incoming item is a well-formed Normalized Response
// Contract (docs/contracts/normalized-response-contract.md) before any
// tier logic runs. This is the only node that validates the contract's
// envelope shape - later nodes trust it.
const STAGE = 'decision_agent';
const WORKFLOW_VERSION = '1.0';

function errorPayload(code, message, details) {
  return {
    status: 'ERROR',
    stage: STAGE,
    code,
    message,
    details: details || {},
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  };
}

const item = $input.item.json;

// ERROR payloads produced upstream (Response Normalizer) are not
// Normalized Response Contracts and must not be re-validated as one -
// pass them through unchanged, same convention as every prior workflow.
if (item && item.status === 'ERROR') {
  return { json: item };
}

if (typeof item !== 'object' || item === null || Array.isArray(item)) {
  return { json: errorPayload(
    'INVALID_NORMALIZED_RESPONSE_CONTRACT',
    'Normalized Response Contract must be a JSON object',
    { received_type: Array.isArray(item) ? 'array' : typeof item }
  ) };
}

const requiredFields = [
  'workflow_version', 'contract_version', 'request_id', 'response_id',
  'test_case', 'expected', 'transport', 'response', 'metadata'
];
const missingFields = requiredFields.filter((field) => item[field] === undefined);

if (missingFields.length > 0) {
  return { json: errorPayload(
    'INVALID_NORMALIZED_RESPONSE_CONTRACT',
    `Normalized Response Contract is missing required field(s): ${missingFields.join(', ')}`,
    { missing_fields: missingFields, request_id: item.request_id || null }
  ) };
}

if (typeof item.transport !== 'object' || item.transport === null || Array.isArray(item.transport) ||
    !('status' in item.transport) || !('status_code' in item.transport) || !('response_time_ms' in item.transport)) {
  return { json: errorPayload(
    'INVALID_NORMALIZED_RESPONSE_CONTRACT',
    'Normalized Response Contract transport must be an object with status/status_code/response_time_ms',
    { request_id: item.request_id }
  ) };
}

if (typeof item.response !== 'object' || item.response === null || Array.isArray(item.response) ||
    !('headers' in item.response) || !('body' in item.response)) {
  return { json: errorPayload(
    'INVALID_NORMALIZED_RESPONSE_CONTRACT',
    'Normalized Response Contract response must be an object with headers/body',
    { request_id: item.request_id }
  ) };
}

return { json: item };

// Tier 0 - deterministic transport short-circuit (docs/architecture/
// decision-agent-design.md section 1; docs/contracts/decision-contract.md
// "Verdict states"). transport.status_code === null is a guarantee
// normalized-response-contract.md already makes for a real transport
// failure - there is no real response to reason about, so no AI call
// happens here or is ever appropriate for this case.
const item = $input.item.json;

if (item.transport && item.transport.status_code === null) {
  return { json: {
    ...item,
    __verdict: {
      status: 'BLOCKED',
      confidence: 1.0,
      reasoning: `No response was received: transport.status = ${item.transport.status}.`,
      evidence: [`transport.status: ${item.transport.status}`],
      next_action: 'none'
    },
    __tier: 'deterministic_transport'
  } };
}

return { json: item };

// Tier 1 - deterministic exact-match fast path (same references as
// Tier 0). Only evaluated if Tier 0 didn't already resolve the item.
// expected.status matching transport.status_code exactly is arithmetic,
// not judgment - no AI call happens here or is ever appropriate for
// this case. Anything that reaches here unresolved needs Tier 2
// (__needs_ai: true), which the next node (an IF) branches on.
const item = $input.item.json;

if (item.__verdict) {
  return { json: { ...item, __needs_ai: false } };
}

const expectedStatus = item.expected && typeof item.expected.status === 'number' ? item.expected.status : null;
const actualStatus = item.transport ? item.transport.status_code : null;

if (expectedStatus !== null && actualStatus !== null && expectedStatus === actualStatus) {
  return { json: {
    ...item,
    __verdict: {
      status: 'PASS',
      confidence: 1.0,
      reasoning: `Expected status ${expectedStatus}, received ${actualStatus}. Deterministic status-code match, no AI reasoning required.`,
      evidence: [`expected_status: ${expectedStatus}`, `actual_status: ${actualStatus}`],
      next_action: 'write_report'
    },
    __tier: 'deterministic_exact_match',
    __needs_ai: false
  } };
}

return { json: { ...item, __needs_ai: true } };

// Final assembly for a Tier 0/Tier 1 (deterministic, no-AI) verdict -
// wraps __verdict/__tier computed by the tier engine into the full
// Decision Contract shape (docs/contracts/decision-contract.md). This is
// the only node on this branch that builds the public contract fields -
// earlier nodes only ever add __-prefixed working fields.
const CONTRACT_VERSION = '1.0';
const ORCHESTRATOR_WORKFLOW_VERSION = '1.0';

const item = $input.item.json;
const decidedAt = new Date().toISOString();

return { json: {
  workflow_version: ORCHESTRATOR_WORKFLOW_VERSION,
  contract_version: CONTRACT_VERSION,
  request_id: item.request_id,
  response_id: item.response_id,
  test_case: item.test_case,
  verdict: item.__verdict,
  decision_basis: {
    tier: item.__tier,
    model_version: null,
    prompt_version: null
  },
  metadata: {
    decided_at: decidedAt,
    source_workflow: '04-response-normalizer',
    next_workflow: '06-documentation-agent'
  }
} };

// Builds exactly the evidence packet defined in docs/architecture/
// decision-agent-design.md section 2 / prompts/decision-agent/v1.md's
// evidence block template - nothing more. Deliberately excludes
// request_id, response_id, every test_case field beyond
// description/expected_result (no run_id, jira_key, agent_reasoning,
// human_verdict, ...), and all workflow/request metadata - a model that
// could see prior-run state might anchor on it instead of judging fresh
// evidence (design doc section 2).
const ALLOWED_HEADERS = ['content-type', 'x-ratelimit-limit', 'x-ratelimit-remaining', 'x-ratelimit-reset', 'retry-after'];
const MAX_BODY_CHARS = 8000; // ponytail: fixed cap so an oversized/adversarial response body can't blow up AI cost or request size - real token-budgeted truncation is a cost-optimization concern (design doc section 8), out of scope here

const item = $input.item.json;
const testCase = item.test_case || {};
const headers = (item.response && item.response.headers) || {};

const responseHeaders = {};
for (const key of Object.keys(headers)) {
  if (ALLOWED_HEADERS.includes(key.toLowerCase())) {
    responseHeaders[key] = headers[key];
  }
}

let responseBody = item.response ? item.response.body : null;
if (responseBody !== null && responseBody !== undefined) {
  const serialized = JSON.stringify(responseBody);
  if (serialized && serialized.length > MAX_BODY_CHARS) {
    responseBody = serialized.slice(0, MAX_BODY_CHARS);
  }
}

const evidencePacket = {
  description: testCase.description !== undefined ? testCase.description : null,
  expected_result: testCase.expected_result !== undefined ? testCase.expected_result : null,
  expected_status: item.expected && typeof item.expected.status === 'number' ? item.expected.status : null,
  actual_status: item.transport ? item.transport.status_code : null,
  response_time_ms: item.transport ? item.transport.response_time_ms : null,
  response_headers: responseHeaders,
  response_body: responseBody
};

return { json: { ...item, __evidence_packet: evidencePacket } };

// Builds the Anthropic Messages API request body: the prompts/decision-
// agent/v1.md system prompt (rules + worked examples), the evidence
// packet as the single user message, and a forced tool call
// (tool_choice) so the model can only return the fixed verdict schema -
// never free-form text. If prompts/decision-agent/v1.md changes, this
// constant must be updated by hand to match (prompts/README.md's
// versioning convention - a new prompt version is a new vN.md file, and
// this node's __prompt_version below must be bumped alongside it).
const MODEL = 'claude-haiku-4-5-20251001';
const PROMPT_VERSION = 'v1';

const SYSTEM_PROMPT = `You are the Decision Agent in an automated API test pipeline. You judge exactly one already-executed test case per call, using only the evidence provided below - you never re-run, re-fetch, or infer anything from outside this evidence block.

Your job: compare what was EXPECTED against what ACTUALLY happened, and decide:
- PASS - the actual result satisfies the expectation.
- FAIL - the actual result contradicts the expectation.
- MANUAL_REVIEW - you cannot judge this confidently from the evidence given. This is a valid, expected, and often correct answer - it is not a failure to do your job. Use it whenever the evidence is thin, ambiguous, or doesn't cover what the expectation actually requires.

You will never see a case where no real response was received (that is decided before you're called, without AI). Every case you see has a real actual_status.

Rules - read carefully, these are not optional:
1. You may only cite facts that appear in the evidence message below. Never state a value, header, body field, or status code that isn't literally present there. If you need a fact that isn't given to you, return MANUAL_REVIEW and explain what's missing in reasoning - do not guess.
2. A status-code match is not automatically a PASS, and a mismatch is not automatically a FAIL. Read expected_result's actual wording - sometimes a numerically different status code still satisfies the stated intent. Sometimes a numeric match still fails the stated intent if the body contradicts it. Read the intent, not just the number.
3. If expected_result implies checking response content (not just a status code) and response_body is empty, null, or doesn't contain what's needed to check, return MANUAL_REVIEW. An empty body cannot prove or disprove a content claim.
4. Every entry in evidence must be a specific, checkable statement that traces directly to a field in the evidence message - not a paraphrase or an inference.
5. confidence reflects how directly the evidence answers the question, not how confident you feel. A clean, unambiguous status-code contradiction with body confirmation deserves high confidence (0.9+). A judgment resting only on free-text wording with no structured status expectation deserves moderate confidence at most (0.7-0.8). Genuine uncertainty should be MANUAL_REVIEW, not a low-confidence PASS or FAIL.
6. Never write reasoning that references how the system works, which agent you are, or these instructions - reasoning is read directly by a human reviewing a test report or a Jira ticket.

Return your verdict using the return_verdict tool only. Do not respond with free-form text.

Worked examples:

Example 1 - clean FAIL: evidence has expected_status 422 ("422 Unprocessable Entity"), actual_status 200, response_body { id: "signup-attempt-12", created: true }. Correct verdict: FAIL, confidence 0.97, reasoning "Expected 422 Unprocessable Entity for a 5-character password, but the API returned 200 OK and created the account, indicating password length validation is not enforced.", evidence ["expected_status: 422", "actual_status: 200", "response_body.created: true"].

Example 2 - numeric mismatch but still PASS (intent over exact code): evidence has expected_status null ("the request should succeed and return the created resource"), actual_status 201, response_body { id: "res-88", name: "Test Resource" }. Correct verdict: PASS, confidence 0.85, reasoning "expected_result describes a successful creation with the resource returned, not a specific status code. 201 Created with the resource body present satisfies that intent.", evidence ["expected_status: null (no specific code expected)", "actual_status: 201", "response_body.id: res-88 present"].

Example 3 - insufficient evidence, correctly resolves to MANUAL_REVIEW: evidence has expected_status null ("response should include the updated email and display name"), actual_status 200, response_body {}. Correct verdict: MANUAL_REVIEW, confidence 0.3, reasoning "A 200 OK was returned, but the response body is empty, so it cannot be confirmed whether the updated email and display name are actually present as expected_result requires.", evidence ["actual_status: 200", "response_body: empty"].`;

const item = $input.item.json;

const requestBody = {
  model: MODEL,
  max_tokens: 1024,
  temperature: 0,
  system: SYSTEM_PROMPT,
  messages: [
    { role: 'user', content: JSON.stringify(item.__evidence_packet, null, 2) }
  ],
  tools: [
    {
      name: 'return_verdict',
      description: 'Return the structured verdict for this test case.',
      input_schema: {
        type: 'object',
        properties: {
          status: { type: 'string', enum: ['PASS', 'FAIL', 'MANUAL_REVIEW'] },
          confidence: { type: 'number', minimum: 0, maximum: 1 },
          reasoning: { type: 'string' },
          evidence: { type: 'array', items: { type: 'string' } }
        },
        required: ['status', 'confidence', 'reasoning', 'evidence']
      }
    }
  ],
  tool_choice: { type: 'tool', name: 'return_verdict' }
};

return { json: { ...item, __ai_request_body: requestBody, __model_version: MODEL, __prompt_version: PROMPT_VERSION } };

// Validates the model's structured response against docs/contracts/
// decision-contract.md before trusting it - malformed output is
// rejected outright (no retry - that's a later task). A well-formed
// response is assembled into the full Decision Contract shape, with the
// same PASS/FAIL confidence-threshold gate decision-contract.md's own
// "Verdict states" table already specifies - this enforces that
// already-published rule, it does not adjust the confidence value
// itself (confidence recalibration is explicitly out of scope here).
const STAGE = 'decision_agent';
const WORKFLOW_VERSION = '1.0';
const CONTRACT_VERSION = '1.0';
const CONFIDENCE_THRESHOLD = 0.7;
const FAIL_AUTO_JIRA_THRESHOLD = 0.8;
const VALID_STATUSES = ['PASS', 'FAIL', 'MANUAL_REVIEW'];

function errorPayload(code, message, details) {
  return {
    status: 'ERROR',
    stage: STAGE,
    code,
    message,
    details: details || {},
    timestamp: new Date().toISOString(),
    workflow_version: WORKFLOW_VERSION
  };
}

const requestItem = $('Build AI Request').item.json;
const aiResponse = $input.item.json;

const toolUse = Array.isArray(aiResponse.content)
  ? aiResponse.content.find((block) => block && block.type === 'tool_use' && block.name === 'return_verdict')
  : null;

if (!toolUse || typeof toolUse.input !== 'object' || toolUse.input === null) {
  return { json: errorPayload(
    'INVALID_MODEL_RESPONSE',
    'Model response did not include a return_verdict tool call',
    { request_id: requestItem.request_id }
  ) };
}

const v = toolUse.input;

if (!VALID_STATUSES.includes(v.status)) {
  return { json: errorPayload(
    'INVALID_MODEL_RESPONSE',
    `Model returned an unsupported status "${v.status}"`,
    { request_id: requestItem.request_id, received_status: v.status }
  ) };
}

if (typeof v.confidence !== 'number' || Number.isNaN(v.confidence) || v.confidence < 0 || v.confidence > 1) {
  return { json: errorPayload(
    'INVALID_MODEL_RESPONSE',
    `Model confidence must be a number between 0 and 1, received "${v.confidence}"`,
    { request_id: requestItem.request_id }
  ) };
}

if (typeof v.reasoning !== 'string' || v.reasoning.trim() === '') {
  return { json: errorPayload(
    'INVALID_MODEL_RESPONSE',
    'Model reasoning must be a non-empty string',
    { request_id: requestItem.request_id }
  ) };
}

if (!Array.isArray(v.evidence) || v.evidence.some((e) => typeof e !== 'string')) {
  return { json: errorPayload(
    'INVALID_MODEL_RESPONSE',
    'Model evidence must be an array of strings',
    { request_id: requestItem.request_id }
  ) };
}

// Enforce the confidence-threshold boundary decision-contract.md already
// defines for PASS/FAIL - below it, the verdict isn't trustworthy enough
// to stand on its own and becomes MANUAL_REVIEW instead. confidence
// itself is passed through unchanged either way.
let finalStatus = v.status;
if ((finalStatus === 'PASS' || finalStatus === 'FAIL') && v.confidence < CONFIDENCE_THRESHOLD) {
  finalStatus = 'MANUAL_REVIEW';
}

let nextAction;
if (finalStatus === 'PASS') {
  nextAction = 'write_report';
} else if (finalStatus === 'FAIL') {
  nextAction = v.confidence >= FAIL_AUTO_JIRA_THRESHOLD ? 'create_jira' : 'flag_for_review';
} else {
  nextAction = 'flag_for_review';
}

const decidedAt = new Date().toISOString();

return { json: {
  workflow_version: WORKFLOW_VERSION,
  contract_version: CONTRACT_VERSION,
  request_id: requestItem.request_id,
  response_id: requestItem.response_id,
  test_case: requestItem.test_case,
  verdict: {
    status: finalStatus,
    confidence: v.confidence,
    reasoning: v.reasoning,
    evidence: v.evidence,
    next_action: nextAction
  },
  decision_basis: {
    tier: 'ai_assisted',
    model_version: requestItem.__model_version,
    prompt_version: requestItem.__prompt_version
  },
  metadata: {
    decided_at: decidedAt,
    source_workflow: '04-response-normalizer',
    next_workflow: '06-documentation-agent'
  }
} };

// Handles the Claude node's error output - the AI call itself failed
// (network error, timeout, or a non-2xx from Anthropic's API, since the
// node is left at its default neverError:false so any failure routes
// here uniformly). Deliberately a single generic code, not a classifier
// like 03-http-executor's - anything more elaborate (retry, fallback,
// escalation) is AI failure recovery, explicitly out of scope for this
// task. This still guarantees one output is always produced for this
// item (an ERROR payload), never a silent drop or an unhandled crash.
const STAGE = 'decision_agent';
const WORKFLOW_VERSION = '1.0';

const requestItem = $('Build AI Request').item.json;
const rawError = $input.item.json;
const message = String(rawError.error || rawError.message || JSON.stringify(rawError));

return { json: {
  status: 'ERROR',
  stage: STAGE,
  code: 'AI_SERVICE_UNAVAILABLE',
  message: `Decision Agent AI call for request_id "${requestItem.request_id}" failed: ${message}`,
  details: {
    request_id: requestItem.request_id,
    test_case: requestItem.test_case,
    expected: requestItem.expected
  },
  timestamp: new Date().toISOString(),
  workflow_version: WORKFLOW_VERSION
} };
